  <div class="bg-gradient-to-br from-emerald-50 to-teal-50 rounded-2xl p-6 border-2 border-emerald-200">
    <div class="flex items-center gap-3 mb-5">
      <div class="w-12 h-12 rounded-xl bg-emerald-100 flex items-center justify-center">
        <svg class="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2m-6 9l2 2 4-4"/></svg>
      </div>
      <h3 class="text-xl font-bold text-emerald-900">Action Steps — Finding the Opportunities Area</h3>
    </div>
    
    <div class="space-y-4">
      
      <div class="flex items-start gap-4 bg-white rounded-xl p-4 shadow-sm">
        <div class="w-10 h-10 rounded-full bg-emerald-500 text-white flex items-center justify-center font-bold text-lg flex-shrink-0">1</div>
        <div>
          <p class="font-semibold text-slate-900">Review the Stages</p>
          <p class="text-slate-600 text-sm">Look at the six stages: New Lead, Contacted, Appointment Booked, Proposal Sent, Won, Lost.</p>
        </div>
      </div>
      <div class="flex items-start gap-4 bg-white rounded-xl p-4 shadow-sm">
        <div class="w-10 h-10 rounded-full bg-emerald-500 text-white flex items-center justify-center font-bold text-lg flex-shrink-0">2</div>
        <div>
          <p class="font-semibold text-slate-900">Adapt for Your Business</p>
          <p class="text-slate-600 text-sm">Would these stages work for your business, or do you need one or two different names?</p>
        </div>
      </div>
      <div class="flex items-start gap-4 bg-white rounded-xl p-4 shadow-sm">
        <div class="w-10 h-10 rounded-full bg-emerald-500 text-white flex items-center justify-center font-bold text-lg flex-shrink-0">3</div>
        <div>
          <p class="font-semibold text-slate-900">Define Your Stages</p>
          <p class="text-slate-600 text-sm">Write down the 4-6 stages that match your sales process.</p>
        </div>
      </div>
    </div>
  </div>
</div>',
      title = 'What Is a Pipeline?',
      lesson_number = 4,
      sort_order = 4,
      updated_at = NOW()
    WHERE id = v_lesson_id;
    
    RAISE NOTICE 'Updated lesson: What Is a Pipeline?';
  END IF;

END $$;


-- Insert Quiz Questions for Lesson: What Is a Pipeline?

DO $$
DECLARE
  v_module_id UUID;
  v_lesson_id UUID;
  v_quiz_id UUID;
BEGIN
  -- Get Module by week number
  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 5 LIMIT 1;
  
  IF v_module_id IS NULL THEN
    RAISE NOTICE 'Module 5 not found';
    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'what-is-pipeline' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson what-is-pipeline not found in module 5';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What is a Pipeline?', 
    '["A list of email templates","The path a lead moves through from first interest to final decision","A social media strategy","A type of contact form"]'::jsonb,
    'The path a lead moves through from first interest to final decision',
    'A Pipeline is the path a lead moves through from first interest to final decision. It visualizes the sales journey with stages like New Lead, Contacted, Appointment Booked, etc.', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What does the ''Lost'' stage mean?', 
    '["You failed as a salesperson","The lead is not moving forward right now in this pipeline","The lead should be deleted forever","You should never contact them again"]'::jsonb,
    'The lead is not moving forward right now in this pipeline',
    'Lost does not mean failure. It simply means the lead is not moving forward in this pipeline right now. They may re-engage later or be suited for a different offer.', 
    2
  )
  RETURNING id INTO v_quiz_id;


  -- Question 3
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Which stage comes after ''Contacted''?', 
    '["Won","Appointment Booked","Lost","New Lead"]'::jsonb,
    'Appointment Booked',
    'The typical flow is: New Lead → Contacted → Appointment Booked → Proposal Sent → Won/Lost. After Contacted comes Appointment Booked.', 
    3
  )
  RETURNING id INTO v_quiz_id;

END $$;
